# --- contextdoc scenario: "Percentage discount" sha256:ad5de808b078 ---
import pytest
from coupon import Coupon, DiscountType

def test_percentage_discount():
    # Step 1: call apply_discount(100.0) on a 20% coupon
    coupon_20 = Coupon(code="SAVE20", discount_type=DiscountType.PERCENTAGE, discount_value=20.0)
    assert coupon_20.apply_discount(100.0) == 80.0

    # Step 2: call apply_discount(100.0) on a 100% coupon
    coupon_100 = Coupon(code="FREE", discount_type=DiscountType.PERCENTAGE, discount_value=100.0)
    assert coupon_100.apply_discount(100.0) == 0.0

    # Step 3: call apply_discount(50.0) on a 200% coupon
    coupon_200 = Coupon(code="OVER", discount_type=DiscountType.PERCENTAGE, discount_value=200.0)
    assert coupon_200.apply_discount(50.0) == 0.0
# --- end scenario ---

# --- contextdoc scenario: "Fixed discount" sha256:821e9a297c16 ---
import pytest
from coupon import Coupon, DiscountType

def test_fixed_discount():
    # Step 1: call apply_discount(50.0) on a $15 fixed coupon
    coupon1 = Coupon(
        code="FIXED15",
        discount_type=DiscountType.FIXED,
        discount_value=15.0
    )
    assert coupon1.apply_discount(50.0) == 35.0

    # Step 2: call apply_discount(10.0) on a $60 fixed coupon
    coupon2 = Coupon(
        code="FIXED60",
        discount_type=DiscountType.FIXED,
        discount_value=60.0
    )
    assert coupon2.apply_discount(10.0) == 0.0
# --- end scenario ---

# --- contextdoc scenario: "Validation guards" sha256:e579f8cc3cd9 ---
import pytest
from datetime import datetime, timedelta
from coupon import Coupon, DiscountType

def test_validation_guards():
    # Step 1: call validate() on a coupon with active=False
    coupon_inactive = Coupon(
        code="INACTIVE", 
        discount_type=DiscountType.FIXED, 
        discount_value=10.0, 
        active=False
    )
    with pytest.raises(ValueError):
        coupon_inactive.validate(100.0)

    # Step 2: call validate() on a coupon with max_uses=2, used_count=2
    coupon_limit = Coupon(
        code="LIMIT", 
        discount_type=DiscountType.FIXED, 
        discount_value=10.0, 
        max_uses=2, 
        used_count=2
    )
    with pytest.raises(ValueError, match="usage limit"):
        coupon_limit.validate(100.0)

    # Step 3: call validate() on a coupon with min_order_amount=50.0, order_total=30.0
    coupon_min = Coupon(
        code="MIN", 
        discount_type=DiscountType.FIXED, 
        discount_value=10.0, 
        min_order_amount=50.0
    )
    with pytest.raises(ValueError, match="minimum"):
        coupon_min.validate(30.0)

    # Step 4: call validate() on a coupon with expires_at 1 hour in the past
    # Using the same logic as _utcnow() to ensure consistency
    from coupon import _utcnow
    past_date = _utcnow() - timedelta(hours=1)
    coupon_expired = Coupon(
        code="EXPIRED", 
        discount_type=DiscountType.FIXED, 
        discount_value=10.0, 
        expires_at=past_date
    )
    with pytest.raises(ValueError, match="expired"):
        coupon_expired.validate(100.0)

    # Step 5: call validate() on a coupon with max_uses=None (unlimited) and used_count=999
    coupon_unlimited = Coupon(
        code="UNLIMITED", 
        discount_type=DiscountType.FIXED, 
        discount_value=10.0, 
        max_uses=None, 
        used_count=999
    )
    # Should not raise
    coupon_unlimited.validate(100.0)
# --- end scenario ---
